rss.channel:
{{ if eq .Title .Site.Title }}{{ .Site.Title }}{{ else }}{{ with .Title }}{{ . }} sur {{ end }}{{ .Site.Title }}{{ end }}
{{ .Permalink }}
Flux RSS des Avis de Vacances de Poste - {{ .Site.Title }}
Hugo -- gohugo.io
{{ site.Language.Locale | default .Site.LanguageCode }}


  {{ "assets/logo-opt.png" | absURL }}
  {{ .Site.Title }}
  {{ .Permalink }}


{{ with .OutputFormats.Get "RSS" }}
    {{ printf "" .Permalink .MediaType.Type | safeHTML }}
{{ end }}

{{/* 🎯 Même filtre que le flux ATS et le jobs-sitemap : les AVP NON archivés,
     reconnus à leur `ref` (absente des pages éditoriales et du mot de la DRH).

     C'était auparavant une liste noire d'URL — a-propos, 404, search — qui
     laissait donc passer toute page ajoutée par la suite : `stats` et
     `developpeurs` s'y étaient glissées, et surtout les 44 AVP archivés,
     si bien que le flux annonçait 44 offres closes pour 2 ouvertes.
     Une liste blanche échoue dans le bon sens : une nouvelle page reste
     dehors tant qu'elle n'est pas un AVP. */}}
{{ range partial "avp-actives.html" .Site.RegularPages }}
  {{ if .Params.ref }}


    {{ .Title }}
    {{ .Permalink }}
    {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" | safeHTML }}
    {{ .Permalink }}
    {{ or .Description .Summary | html }}

    {{/* 🎯 ILLUSTRATION DE L'AVP — même source que les aperçus sociaux,
         cf. partials/avp-image-sociale.html : le PNG de `featured_image`
         vit dans assets/ et n'est jamais publié, le partial rend donc une
         variante réellement servie. */}}
    {{ if .Params.featured_image }}
      {{ $img := partial "avp-image-sociale.html" . }}


    {{ end }}

  {{ end }}
{{ end }}
